export * as ToolCall from './tool-call.tsx';
export type {
  CodeProps as ToolCallCodeProps,
  RootOwnProps as ToolCallRootOwnProps,
  RootProps as ToolCallRootProps,
  SectionProps as ToolCallSectionProps,
  StatusProps as ToolCallStatusProps,
  ToolCallStatus,
  TriggerProps as ToolCallTriggerProps,
} from './tool-call.tsx';

@layer hj.components {
  /* Customise: --hj-tool-call-radius · --hj-tool-call-bg */
  .hj-tool-call {
    border-radius: var(--hj-tool-call-radius, var(--hj-radius-md));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-tool-call-bg, var(--hj-bg-soft));
    box-shadow: inset 0 0 0 1px var(--hj-line);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    overflow: hidden;
  }
  .hj-tool-call[data-status='needs-approval'] {
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--hj-warning) 45%, transparent);
  }
  .hj-tool-call[data-status='failed'] {
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--hj-danger) 35%, transparent);
  }

  .hj-tool-call-trigger {
    display: flex;
    align-items: center;
    gap: calc(10px * var(--hj-density));
    width: 100%;
    min-height: calc(44px * var(--hj-density-size));
    padding: 0 calc(12px * var(--hj-density)) 0 calc(14px * var(--hj-density));
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    text-align: left;
    cursor: pointer;
    transition: background-color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-tool-call-trigger:hover {
    background: color-mix(in srgb, var(--hj-fg) 4%, transparent);
  }
  .hj-tool-call-trigger:focus-visible {
    outline-offset: -2px;
  }
  .hj-tool-call-icon {
    display: inline-flex;
    flex: none;
    color: var(--hj-fg-mute);
    font-size: 16px;
    line-height: 0;
  }
  .hj-tool-call-icon svg,
  .hj-tool-call-chevron svg {
    width: 1em;
    height: 1em;
  }
  .hj-tool-call-name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font: 500 13px / 1.3 var(--hj-font-mono);
  }
  .hj-tool-call-chevron {
    display: inline-flex;
    flex: none;
    margin-left: calc(4px * var(--hj-density));
    color: var(--hj-fg-mute);
    font-size: 16px;
    line-height: 0;
    transition: transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle);
  }
  .hj-tool-call-trigger[data-panel-open] .hj-tool-call-chevron {
    transform: rotate(180deg);
  }

  /* Status: word + glyph + tint. */
  .hj-tool-call-status {
    display: inline-flex;
    align-items: center;
    gap: calc(5px * var(--hj-density));
    margin-left: auto;
    flex: none;
    height: 24px;
    padding: 0 calc(9px * var(--hj-density)) 0 calc(7px * var(--hj-density));
    border-radius: var(--hj-radius-pill);
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg-dim);
    font-size: 12px;
    font-weight: 600;
  }
  .hj-tool-call-status[data-status='done'] {
    background: var(--hj-success-soft);
    color: var(--hj-success);
  }
  .hj-tool-call-status[data-status='failed'] {
    background: var(--hj-danger-soft);
    color: var(--hj-danger);
  }
  .hj-tool-call-status[data-status='needs-approval'] {
    background: var(--hj-warning-soft);
    color: var(--hj-warning);
  }
  .hj-tool-call-status[data-status='running'] {
    background: var(--hj-accent-soft);
    color: var(--hj-accent);
  }
  .hj-tool-call-status-glyph {
    display: inline-grid;
    place-items: center;
    width: 14px;
    height: 14px;
    line-height: 0;
  }
  .hj-tool-call-status-glyph svg {
    width: 14px;
    height: 14px;
  }
  .hj-tool-call-duration {
    margin-left: 2px;
    font: 500 11px / 1 var(--hj-font-mono);
    font-variant-numeric: tabular-nums;
    opacity: 0.8;
  }
  .hj-tool-call-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    box-shadow: inset 0 0 0 1.5px currentColor;
  }
  /* The ink ring: a constant turn (pulses under reduced motion). */
  .hj-tool-call-spinner {
    position: relative;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    animation: var(--hj-anim-spin);
  }
  .hj-tool-call-spinner::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 50%;
    background: conic-gradient(from 0deg, transparent 0deg 40deg, currentColor 360deg);
    mask: radial-gradient(farthest-side, transparent calc(100% - 2px), black calc(100% - 1.5px));
  }

  /* The one layout transition: the panel's height, clipped and short. */
  .hj-tool-call-panel {
    height: var(--collapsible-panel-height);
    overflow: hidden;
    transition: height var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle);
  }
  .hj-tool-call-panel[data-starting-style],
  .hj-tool-call-panel[data-ending-style] {
    height: 0;
  }
  .hj-tool-call-panel[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }
  .hj-tool-call-body {
    display: grid;
    gap: calc(12px * var(--hj-density));
    padding: calc(4px * var(--hj-density)) calc(14px * var(--hj-density))
      calc(14px * var(--hj-density));
    border-top: 1px solid var(--hj-line);
  }
  .hj-tool-call-section {
    display: grid;
    gap: calc(6px * var(--hj-density));
    min-width: 0;
    padding-top: calc(10px * var(--hj-density));
  }
  .hj-tool-call-label {
    font: var(--hj-type-eyebrow);
    letter-spacing: var(--hj-tracking-eyebrow);
    text-transform: uppercase;
    color: var(--hj-fg-mute);
  }
  .hj-tool-call-code {
    margin: 0;
    padding: calc(10px * var(--hj-density)) calc(12px * var(--hj-density));
    max-height: 220px;
    overflow: auto;
    border-radius: var(--hj-radius-xs);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
    color: var(--hj-fg-dim);
    font: 400 12px / 1.6 var(--hj-font-mono);
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    tab-size: 2;
  }
  .hj-tool-call[data-status='failed'] .hj-tool-call-section:last-child .hj-tool-call-code {
    color: var(--hj-danger);
  }

  .hj-tool-call-approval {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: calc(8px * var(--hj-density)) calc(12px * var(--hj-density));
    padding: calc(12px * var(--hj-density));
    border-radius: var(--hj-radius-sm);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-warning-soft);
    font-size: 13.5px;
    line-height: 1.45;
  }
  .hj-tool-call-approval > :first-child {
    flex: 1;
    min-width: 18ch;
  }
}

'use client';
import { Collapsible as Base } from '@base-ui/react/collapsible';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart } from '../../system/part.tsx';
import type { ElementPartProps } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

export type ToolCallStatus = 'pending' | 'running' | 'done' | 'failed' | 'needs-approval';

const StatusContext = React.createContext<ToolCallStatus>('pending');

/** Props hanji adds to the Root. */
export interface RootOwnProps {
  /**
   * pending (queued) · running (spinner) · done · failed · needs-approval (a person must
   * approve before it runs — opens by default).
   */
  status?: ToolCallStatus;
}
export interface RootProps extends RootOwnProps, Base.Root.Props {}

/**
 * One tool the assistant called: a collapsible card with its name, status, arguments and result.
 *
 * @example
 * <ToolCall.Root status="done">
 *   <ToolCall.Trigger><ToolCall.Name>library.search</ToolCall.Name><ToolCall.Status duration="0.4 s" /></ToolCall.Trigger>
 *   <ToolCall.Panel>
 *     <ToolCall.Section label="Arguments"><ToolCall.Code>{json}</ToolCall.Code></ToolCall.Section>
 *   </ToolCall.Panel>
 * </ToolCall.Root>
 */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    status = 'pending',
    className,
    defaultOpen,
    ...rest
  } = withDefaults(config, 'ToolCall.Root', props);
  return (
    <StatusContext.Provider value={status}>
      <Base.Root
        defaultOpen={defaultOpen ?? status === 'needs-approval'}
        {...rest}
        data-status={status}
        className={cls(config, 'ToolCall.Root', 'hj-tool-call', className)}
      />
    </StatusContext.Provider>
  );
}

export interface TriggerOwnProps {
  /** Replace the tool glyph at the start. */
  icon?: React.ReactNode;
}
export interface TriggerProps extends TriggerOwnProps, Base.Trigger.Props {}

/** The header row: tool glyph, children (Name, Status), and a chevron that turns when open. */
export function Trigger(props: TriggerProps): React.ReactElement {
  const config = useHanjiConfig();
  const { icon, className, children, ...rest } = withDefaults(config, 'ToolCall.Trigger', props);
  const styled = !config.unstyled;
  return (
    <Base.Trigger
      {...rest}
      className={cls(config, 'ToolCall.Trigger', 'hj-tool-call-trigger', className)}
    >
      <span className={styled ? 'hj-tool-call-icon' : undefined} aria-hidden="true">
        {icon ?? config.icons.tool}
      </span>
      {children}
      <span className={styled ? 'hj-tool-call-chevron' : undefined} aria-hidden="true">
        {config.icons.chevronDown}
      </span>
    </Base.Trigger>
  );
}

/** The tool's name, in mono. */
export const Name: (props: ElementPartProps<'span'>) => React.ReactElement = elementPart(
  'span',
  'ToolCall.Name',
  'hj-tool-call-name',
);

const STATUS_WORD: Record<ToolCallStatus, string> = {
  pending: 'Queued',
  running: 'Running',
  done: 'Done',
  failed: 'Failed',
  'needs-approval': 'Needs approval',
};

export interface StatusOwnProps {
  /** How long it took, e.g. `0.4 s`. Shown after the word. */
  duration?: string;
}
export interface StatusProps extends StatusOwnProps, React.ComponentProps<'span'> {}

/** Word + glyph + tint for the Root's status — never colour alone. Children replace the word. */
export function Status(props: StatusProps): React.ReactElement {
  const config = useHanjiConfig();
  const status = React.useContext(StatusContext);
  const { duration, className, children, ...rest } = withDefaults(config, 'ToolCall.Status', props);
  const styled = !config.unstyled;
  const glyph =
    status === 'running' ? (
      <span className={styled ? 'hj-tool-call-spinner' : undefined} />
    ) : status === 'done' ? (
      config.icons.checkCircle
    ) : status === 'failed' ? (
      config.icons.xCircle
    ) : status === 'needs-approval' ? (
      config.icons.alert
    ) : (
      <span className={styled ? 'hj-tool-call-dot' : undefined} />
    );
  return (
    <span
      {...rest}
      data-status={status}
      className={
        cls(config, 'ToolCall.Status', 'hj-tool-call-status', className) as string | undefined
      }
    >
      <span className={styled ? 'hj-tool-call-status-glyph' : undefined} aria-hidden="true">
        {glyph}
      </span>
      {children ?? STATUS_WORD[status]}
      {duration ? (
        <span className={styled ? 'hj-tool-call-duration' : undefined}>{duration}</span>
      ) : null}
    </span>
  );
}

/** The details. Height reveal via Base UI's --collapsible-panel-height. */
export function Panel(props: Base.Panel.Props): React.ReactElement {
  const config = useHanjiConfig();
  const { className, children, ...rest } = withDefaults(config, 'ToolCall.Panel', props);
  return (
    <Base.Panel
      {...rest}
      className={cls(config, 'ToolCall.Panel', 'hj-tool-call-panel', className)}
    >
      <div className={config.unstyled ? undefined : 'hj-tool-call-body'}>{children}</div>
    </Base.Panel>
  );
}

export interface SectionOwnProps {
  /** Eyebrow above the block: Arguments, Result, Error. */
  label?: React.ReactNode;
}
export interface SectionProps
  extends SectionOwnProps, Omit<React.ComponentProps<'section'>, 'className'> {
  className?: string;
  render?: useRender.RenderProp;
}

/** A labelled block inside the panel. */
export function Section(props: SectionProps): React.ReactElement {
  const config = useHanjiConfig();
  const { label, className, render, children, ...rest } = withDefaults(
    config,
    'ToolCall.Section',
    props,
  );
  return useRender({
    render,
    defaultTagName: 'section',
    props: {
      ...rest,
      className: cls(config, 'ToolCall.Section', 'hj-tool-call-section', className) as
        | string
        | undefined,
      children: (
        <>
          {label ? (
            <div className={config.unstyled ? undefined : 'hj-tool-call-label'}>{label}</div>
          ) : null}
          {children}
        </>
      ),
    },
  });
}

/** Arguments or a result, in mono. Objects are shown as indented JSON. */
export interface CodeOwnProps {
  /** A value to show as JSON. Children win when both are given. */
  value?: unknown;
}
export interface CodeProps extends CodeOwnProps, React.ComponentProps<'pre'> {}

export function Code(props: CodeProps): React.ReactElement {
  const config = useHanjiConfig();
  const { value, className, children, ...rest } = withDefaults(config, 'ToolCall.Code', props);
  const text =
    children ??
    (value === undefined
      ? null
      : typeof value === 'string'
        ? value
        : JSON.stringify(value, null, 2));
  return (
    <pre
      {...rest}
      className={cls(config, 'ToolCall.Code', 'hj-tool-call-code', className) as string | undefined}
    >
      <code>{text}</code>
    </pre>
  );
}

/**
 * The human-in-the-loop row: what will happen, and Approve / Deny. Use for anything that spends
 * money, sends, deletes or changes access — never run those without a person approving.
 */
export const Approval: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'ToolCall.Approval',
  'hj-tool-call-approval',
);
